@extends('layouts.officer') @section('title','Peta Penugasan') @section('breadcrumb','Peta Penugasan')
@push('styles')<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css">@endpush
@section('content')<h1 class="page-title">Peta Penugasan</h1><p class="muted mb-4">Peta hanya menampilkan lokasi laporan yang sedang ditugaskan kepada Anda.</p><div class="panel"><div class="row g-3 mb-3"><div class="col-md-4"><select id="categoryFilter" class="form-select"><option value="all">Semua kategori</option><option value="pju_rusak">PJU Rusak</option><option value="area_gelap">Area Gelap</option><option value="begal_curas">Begal/Curas</option></select></div><div class="col-md-4"><select id="statusFilter" class="form-select"><option value="all">Semua status</option><option value="assigned">Ditugaskan</option><option value="accepted">Diterima</option><option value="in_progress">Sedang dikerjakan</option><option value="awaiting_confirmation">Menunggu konfirmasi</option></select></div></div><div id="officerMap" style="height:560px;border-radius:12px;z-index:1"></div><p id="emptyMap" class="muted small mt-3 mb-0" style="display:none">Belum ada lokasi penugasan dengan koordinat yang valid.</p></div>@endsection
@push('scripts')<script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><script>
const points=@json($points);const map=L.map('officerMap').setView([3.5952,98.6722],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap'}).addTo(map);let layers=[];
function draw(){layers.forEach(l=>map.removeLayer(l));layers=[];const c=document.getElementById('categoryFilter').value,s=document.getElementById('statusFilter').value;const visible=points.filter(p=>(c==='all'||p.category===c)&&(s==='all'||p.status===s));visible.forEach(p=>{const marker=L.marker([p.lat,p.lng]).addTo(map).bindPopup(`<strong>${p.label}</strong><br>${p.location??'Lokasi tidak diketahui'}<br><small>${p.status.replaceAll('_',' ')}</small><br><a href="${p.url}">Buka detail tugas</a>`);layers.push(marker)});document.getElementById('emptyMap').style.display=visible.length?'none':'block';if(visible.length)map.fitBounds(L.featureGroup(layers).getBounds().pad(.15));else map.setView([3.5952,98.6722],12)}document.getElementById('categoryFilter').addEventListener('change',draw);document.getElementById('statusFilter').addEventListener('change',draw);draw();
</script>@endpush
